package workbench.injector.l02.demo;

import java.net.URI;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.ExecutableElement;
import javax.lang.model.element.TypeElement;
import javax.lang.model.element.VariableElement;
import javax.lang.model.type.TypeMirror;
import javax.lang.model.util.ElementFilter;
import javax.tools.Diagnostic;
import javax.tools.DiagnosticCollector;
import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.SimpleJavaFileObject;
import javax.tools.ToolProvider;
import workbench.injector.annotations.Component;
import workbench.injector.annotations.Inject;

// The closest Java equivalent: a javac annotation processor that walks each @Component's graph and reports a
// missing binding or a cycle with its path, on the exact parameter, through the Messager. (It does the first
// two checks only; the duplicates need modules.) main() runs javac in memory on two broken Java plans.
//   ./gradlew :injector:demo -Pmain=workbench.injector.l02.demo.CompileTimeMistakesDemoJava
public class CompileTimeMistakesDemoJava {

    @SupportedAnnotationTypes("workbench.injector.annotations.Component")
    public static class GraphCheckProcessor extends AbstractProcessor {

        @Override
        public SourceVersion getSupportedSourceVersion() {
            return SourceVersion.latestSupported();
        }

        @Override
        public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment round) {
            for (Element component : round.getElementsAnnotatedWith(Component.class)) {             // 1. Find
                for (ExecutableElement entry : ElementFilter.methodsIn(component.getEnclosedElements())) {
                    walk(entry.getReturnType(), new ArrayList<>(), new HashSet<>(), entry);
                }
            }
            return true;
        }

        /** Depth first, with the path the walk is on: the same walk as the KSP processor's creationOrder. */
        private void walk(TypeMirror type, List<String> path, Set<String> done, Element askedBy) {
            TypeElement cls = (TypeElement) processingEnv.getTypeUtils().asElement(type);
            String name = cls.getSimpleName().toString();
            if (done.contains(name)) return;
            if (path.contains(name)) {                                                               // 2. Check
                List<String> loop = new ArrayList<>(path.subList(path.indexOf(name), path.size()));
                loop.add(name);
                error("Dependency cycle: " + String.join(" needs ", loop), askedBy);
                return;
            }
            ExecutableElement constructor = ElementFilter.constructorsIn(cls.getEnclosedElements()).stream()
                    .filter(c -> c.getAnnotation(Inject.class) != null).findFirst().orElse(null);
            if (constructor == null) {
                List<String> needs = new ArrayList<>(path);
                needs.add(name);
                error(String.join(" needs ", needs) + ": nobody provides " + name, askedBy);
                return;
            }
            path.add(name);
            for (VariableElement p : constructor.getParameters()) walk(p.asType(), path, done, p);    // 3. Read
            path.remove(path.size() - 1);
            done.add(name);
        }

        private void error(String message, Element element) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, message, element);
        }
    }

    public static void main(String[] args) {
        List<JavaFileObject> sources = List.of(
                source("movemate/missing/Missing.java", """
                        package movemate.missing;

                        import workbench.injector.annotations.*;

                        class Route { @Inject Route() {} }
                        class Driver { Driver(Route route) {} }                       // forgot @Inject
                        class Truck { @Inject Truck(Driver driver) {} }
                        class Crew { @Inject Crew(Truck truck) {} }
                        class MovingDay { @Inject MovingDay(Crew crew) {} }

                        @Component interface MissingPlan { MovingDay movingDay(); }
                        """),
                source("movemate/cycle/Cycle.java", """
                        package movemate.cycle;

                        import workbench.injector.annotations.*;

                        class Route { @Inject Route() {} }
                        class Driver { @Inject Driver(Route route, Truck truck) {} }  // waits for the truck
                        class Truck { @Inject Truck(Driver driver) {} }               // which waits for the driver
                        class Crew { @Inject Crew(Truck truck) {} }
                        class MovingDay { @Inject MovingDay(Crew crew) {} }

                        @Component interface CyclePlan { MovingDay movingDay(); }
                        """));
        JavaCompiler javac = ToolProvider.getSystemJavaCompiler();
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        JavaCompiler.CompilationTask task = javac.getTask(null, null, diagnostics,
                List.of("-classpath", System.getProperty("java.class.path"), "-proc:only"), null, sources);
        task.setProcessors(List.of(new GraphCheckProcessor()));
        System.out.println("javac succeeded: " + task.call());
        for (Diagnostic<? extends JavaFileObject> d : diagnostics.getDiagnostics()) {
            String file = d.getSource().getName().substring(d.getSource().getName().lastIndexOf('/') + 1);
            System.out.println(file + ":" + d.getLineNumber() + ": " + d.getKind().toString().toLowerCase() + ": " + d.getMessage(null));
        }
    }

    private static JavaFileObject source(String path, String text) {
        return new SimpleJavaFileObject(URI.create("string:///" + path), JavaFileObject.Kind.SOURCE) {
            @Override
            public CharSequence getCharContent(boolean ignoreEncodingErrors) {
                return text;
            }
        };
    }
}

sections.body:
So far every binding came from an `@Inject` constructor. That works for your own classes. But MoveMate's `Route` now comes from a maps library, and you can't put a sticky note on a class you can't edit. A **module** fills that gap: an object whose functions say how to get such things. Each function marked `@Provides` is a binding, and its parameters are its own dependencies:

```java
// The same module in Java: a Kotlin object compiles to a final class with one INSTANCE
@Module
public final class RouteModule {
    public static final RouteModule INSTANCE = new RouteModule();
    private RouteModule() { }

    @Provides @Singleton @Named("highway")
    public Route highway() { return new Route("highway", 42); }

    @Provides @Singleton @Named("back roads")
    public Route backRoads() { return new Route("back roads", 51); }
}
```

```kotlin
@Module
object RouteModule {
    @Provides @Singleton @Named("highway")
    fun highway(): Route = Route("highway", 42)

    @Provides @Singleton @Named("back roads")
    fun backRoads(): Route = Route("back roads", 51)
}
```

Take the names away first, as in the third broken crew, and the plan has two answers to one question. The reflection container shrugged and kept whichever one it read last. The processor's duplicate check groups every `@Provides` function by its key, the type plus any qualifier. Then it reports every binding after the first on its own line: `Twice.kt:13: Route is provided twice: by RouteModule.highway() and by RouteModule.backRoads().` An `@Inject` constructor counts too. Provide a `Route` from a module while `Route` also has an `@Inject` constructor, and the message says `by Route's @Inject constructor and by RouteModule.route()`.

The fix is a **qualifier**: a name that tells two bindings of the same type apart. `@Named("highway")` on a `@Provides` function marks one binding, and `@Named("highway")` on a parameter asks for exactly that one:

```java
public class Driver {
    @Inject
    public Driver(@Named("highway") Route route) { /* ... */ }
}

public class MovingDay {
    @Inject
    public MovingDay(Crew crew, @Named("back roads") Route familyRoute) { /* ... */ }
}
```

```kotlin
@Singleton
class Driver @Inject constructor(@Named("highway") val route: Route)

@Singleton
class MovingDay @Inject constructor(val crew: Crew, @Named("back roads") val familyRoute: Route)
```

Now the truck takes the highway, and the family follows in their own car on the back roads. The generated plan names each route after its qualifier, so the two never mix: `private val highwayRoute: Route = RouteModule.highway()`, `private val backRoadsRoute: Route = RouteModule.backRoads()`, and the driver's line reads `DriverFactory.create(highwayRoute)`.

A qualifier is part of the key, so a misspelt one is simply a missing binding. Ask for `@Named("hihgway")`, a road no map has heard of, and the walk says so, path and all: `MovingDay needs Crew needs Truck needs Driver needs @Named("hihgway") Route: nobody provides @Named("hihgway") Route.`

Duplicates belong to the modules, not to one component, so the processor checks them once per build, before it walks any component. Then each component's walk adds what it finds. Missing, circular or doubled, every mistake gets its own line in one build, and a component is written only when its plan is clean. When a component isn't written, the app code that uses it can't compile either. So KSP adds follow-on lines such as `MovingDayApp.kt:6: Unresolved reference 'GeneratedMovingDayComponent'.` Fix the first errors; those go away with them.

That leaves the limit of today's checks. They see what the plan is made of: types, names and constructors. They can't tell you that a route of 42 minutes is a bad one, or that a constructor will throw on the day. Those stay run-time problems.

