fun findCycle(needs: Map<String, List<String>>, start: String): List<String>? {
    val done = mutableSetOf<String>()
    val path = mutableListOf<String>()
    fun visit(name: String): List<String>? {
        if (name in done) return null                                  // finished: shared, not a loop
        if (name in path) return path.dropWhile { it != name } + name  // back where we started
        path += name                                                   // on the way in
        for (d in needs[name].orEmpty()) visit(d)?.let { return it }
        path.removeAt(path.lastIndex)                                  // on the way out
        done += name
        return null
    }
    return visit(start)
}
// findCycle(mapOf("Truck" to listOf("Driver"), "Driver" to listOf("Truck")), "Truck") == [Truck, Driver, Truck]

