static List<String> findCycle(Map<String, List<String>> needs, String start) {
    return visit(start, needs, new HashSet<>(), new ArrayList<>());
}

static List<String> visit(String name, Map<String, List<String>> needs, Set<String> done, List<String> path) {
    if (done.contains(name)) return null;                         // finished: shared, not a loop
    if (path.contains(name)) {                                    // back where we started
        List<String> loop = new ArrayList<>(path.subList(path.indexOf(name), path.size()));
        loop.add(name);
        return loop;
    }
    path.add(name);                                               // on the way in
    for (String d : needs.getOrDefault(name, List.of())) {
        List<String> loop = visit(d, needs, done, path);
        if (loop != null) return loop;
    }
    path.remove(path.size() - 1);                                 // on the way out
    done.add(name);
    return null;
}
